package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.character.*;
import dev.tacticalcombat.rules.RulesProfiles;
import dev.tacticalcombat.rules.srd.SrdAuthoring;
import dev.tacticalcombat.uiapi.*;
import java.nio.file.*;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;
import static dev.tacticalcombat.uiapi.UiApiService.Operation.*;

/** Dashboard projections, edit envelopes and authority boundaries against the real service. */
public final class DashboardUiTests {
    private static int count;
    private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);count++;}
    private static JsonObject ok(UiApiService api,CharacterRepository.Principal p,UiApiService.Operation op,JsonObject args){var r=api.handle(p,op,args);check(r.code().equals("OK"),op+": "+r.message());return r.data();}
    private static void denied(UiApiService api,CharacterRepository.Principal p,UiApiService.Operation op,JsonObject args){check(!api.handle(p,op,args).code().equals("OK"),"must reject "+op);}
    public static void run() throws Exception {
        check(DashboardModel.XP.length==20&&DashboardModel.XP[1]==300&&DashboardModel.XP[2]==900&&DashboardModel.XP[19]==355000,"verified 2014 cumulative XP thresholds");
        for(int i=1;i<DashboardModel.XP.length;i++)check(DashboardModel.XP[i]>DashboardModel.XP[i-1],"XP thresholds strictly increase");
        check(DashboardModel.Tab.values().length==10,"three primary views and seven retained sections");for(var tab:DashboardModel.Tab.values())check(!DashboardModel.title(tab).isBlank(),"tab has readable title");
        Path dir=Files.createTempDirectory("dashboard-ui");var repo=new CharacterRepository(dir.resolve("campaigns.json"));var library=new LibraryRepository(dir.resolve("library.json"));var api=new UiApiService(repo,library,(op,a)->{throw new IllegalArgumentException("world unavailable");});var owner=new CharacterRepository.Principal(UUID.randomUUID(),true);var outsider=new CharacterRepository.Principal(UUID.randomUUID(),false);
        JsonObject source=ok(api,owner,LIBRARY_CREATE,args("profile",RulesProfiles.SRD,"mode","MANUAL","sheet",null));String sourceId=text(source,"id");DashboardSource librarySource=new DashboardSource(true,sourceId);check(librarySource.read()==LIBRARY_GET&&librarySource.edit()==LIBRARY_UPDATE,"library dashboard uses library contract");
        JsonObject identity=SheetSections.read(source.getAsJsonObject("sheet"),"identity");identity.addProperty("species","Human");identity.addProperty("characterClass","Fighter");identity.addProperty("subclass","Champion");identity.addProperty("background","Acolyte");source=ok(api,owner,LIBRARY_UPDATE,librarySource.sectionArgs(source,"identity",identity));
        JsonObject progression=SheetSections.read(source.getAsJsonObject("sheet"),"progression");progression.addProperty("recordedLevel",2);progression.addProperty("xp",600);progression.addProperty("mode","XP");source=ok(api,owner,LIBRARY_UPDATE,librarySource.sectionArgs(source,"progression",progression));var xp=DashboardModel.xp(source.getAsJsonObject("sheet"));check(xp.level()==2&&xp.lower()==300&&xp.upper()==900&&Math.abs(xp.fraction()-.5)<.0001,"level 2 XP progress uses 300–900 interval");
        progression.addProperty("mode","MILESTONE");source=ok(api,owner,LIBRARY_UPDATE,librarySource.sectionArgs(source,"progression",progression));check(DashboardModel.xp(source.getAsJsonObject("sheet")).label().contains("Milestone")&&DashboardModel.xp(source.getAsJsonObject("sheet")).fraction()==0,"milestone avoids misleading percentage");progression.addProperty("mode","DM_MANAGED");source=ok(api,owner,LIBRARY_UPDATE,librarySource.sectionArgs(source,"progression",progression));check(DashboardModel.xp(source.getAsJsonObject("sheet")).label().contains("DM-managed"),"DM-managed advancement labelled");
        JsonObject trackers=SheetSections.read(source.getAsJsonObject("sheet"),"trackers");trackers.addProperty("inspiration",true);trackers.addProperty("deathSuccesses",2);trackers.addProperty("exhaustion",1);source=ok(api,owner,LIBRARY_UPDATE,librarySource.sectionArgs(source,"trackers",trackers));
        var item=new SheetSections.Item("custom:sword","","Practice sword",1,true,"main_hand",List.of("manual"),"sheet only","minecraft:wooden_sword");source=ok(api,owner,LIBRARY_UPDATE,librarySource.sectionArgs(source,"inventory",SheetSections.JSON.toJsonTree(new SheetSections.Inventory(List.of(item),1,2,3,4,5)).getAsJsonObject()));
        var condition=new SheetSections.Feature("custom:prone",SheetSections.FeatureKind.CONDITION,"Prone","Recorded condition","manual",SheetSections.Automation.MANUAL,2L,null,null,List.of());source=ok(api,owner,LIBRARY_UPDATE,librarySource.sectionArgs(source,"features",SheetSections.JSON.toJsonTree(new SheetSections.Features(List.of(condition),List.of())).getAsJsonObject()));
        var spell=new SheetSections.SpellDefinition("custom:spark","Spark",0,"Evocation","1 action","30 feet","Instant",true,true,false,"",false,false,"Manual spell.","","custom/manual",true);var spellbook=new SheetSections.Spellbook(List.of(spell),List.of(new SheetSections.SpellSelection(spell.id(),true,true,false,"manual","")),List.of(new SheetSections.Slot(1,1,2,"manual")),"INT",12,4);source=ok(api,owner,LIBRARY_UPDATE,librarySource.sectionArgs(source,"spellbook",SheetSections.JSON.toJsonTree(spellbook).getAsJsonObject()));
        check(DashboardModel.combat(source,true).size()==6,"library SRD dashboard derives display through existing codec");check(DashboardModel.abilities(source).size()==6,"all six canonical abilities projected together");check(DashboardModel.skills(source).size()==18,"full 2014 skill list projected without inventing proficiency automation");check(DashboardModel.header(source,true,false,false).contains("Personal library source")&&DashboardModel.header(source,true,false,false).contains("Human"),"library source identity remains explicit");check(DashboardModel.editable(source,true,owner.id().toString(),false),"library source editable by its owner projection");
        source=ok(api,owner,MANUAL_UPDATE,librarySource.manualArgs(source,new RpgRecords.Change(RpgRecords.Action.DEATH_FAILURES,"trackers","",0,2)));check(SheetSections.read(source.getAsJsonObject("sheet"),"trackers").get("deathFailures").getAsInt()==2,"library manual tracker uses server operation");denied(api,outsider,LIBRARY_GET,args("character",sourceId));
        source=ok(api,owner,LIBRARY_FINALIZE,args("character",sourceId,"revision",revision(source)));JsonObject campaign=ok(api,owner,CAMPAIGN_CREATE,args("name","Dashboard Campaign"));JsonObject copy=ok(api,owner,LIBRARY_SUBMIT,args("character",sourceId,"revision",revision(source),"campaign",text(campaign,"id"),"submission",UUID.randomUUID()));String copyId=text(copy,"id");DashboardSource campaignSource=new DashboardSource(false,copyId);check(campaignSource.read()==CHARACTER_GET&&campaignSource.edit()==CHARACTER_EDIT,"campaign dashboard uses campaign contract");check(!text(copy,"id").equals(sourceId)&&text(copy,"campaign").equals(text(campaign,"id")),"dashboard preserves source/copy identities");check(DashboardModel.header(copy,false,false,false).contains("awaiting approval"),"campaign approval state projected");
        var health=SrdAuthoring.data(source.getAsJsonObject("sheet"));var beforeCombat=health.deepCopy();health.addProperty("hp",7);health.addProperty("temporary_hp",2);source=ok(api,owner,LIBRARY_UPDATE,librarySource.sectionArgs(source,"combat",health));var savedHealth=SrdAuthoring.data(source.getAsJsonObject("sheet"));check(savedHealth.get("hp").getAsInt()==7&&savedHealth.get("temporary_hp").getAsInt()==2,"Library health controls persist through existing authoring endpoint");for(String key:beforeCombat.keySet())if(!Set.of("hp","temporary_hp").contains(key))check(beforeCombat.get(key).equals(savedHealth.get(key)),"Health preserves other combat inputs "+key);check(SrdAuthoring.data(copy.getAsJsonObject("sheet")).get("hp").getAsInt()==beforeCombat.get("hp").getAsInt(),"Library health edit does not heal or damage independent campaign copy");denied(api,owner,CHARACTER_EDIT,campaignSource.sectionArgs(copy,"combat",health));check(SrdAuthoring.data(ok(api,owner,CHARACTER_GET,campaignSource.readArgs()).getAsJsonObject("sheet")).equals(SrdAuthoring.data(copy.getAsJsonObject("sheet"))),"Unsupported campaign health authoring is rejected without mutation");
        var prof=SheetSections.read(source.getAsJsonObject("sheet"),"proficiencies");prof.getAsJsonArray("skills").add("Athletics");prof.getAsJsonArray("expertise").add("Athletics");var projection=source.deepCopy();projection.add("sheet",SheetSections.update(projection.getAsJsonObject("sheet"),"proficiencies",prof));var athletics=DashboardModel.checks(projection,false).stream().filter(c->c.name().equals("Athletics")).findFirst().orElseThrow();check(athletics.expertise()&&athletics.proficiency()==4&&athletics.total()==athletics.base()+4,"Manual skill projection includes recorded expertise exactly once");check(athletics.breakdown().contains("combat engine does not consume"),"Recorded totals never claim authoritative dice effects");check(DashboardModel.checks(projection,true).size()==6,"All six saves share grouped check projection");
        copy=ok(api,owner,CHARACTER_APPROVE,args("character",copyId,"revision",revision(copy)));long approvedRevision=revision(copy);JsonObject details=SheetSections.read(copy.getAsJsonObject("sheet"),"identity");details.addProperty("biography","Edited with explicit campaign warning");copy=ok(api,owner,CHARACTER_EDIT,campaignSource.sectionArgs(copy,"identity",details));check(!flag(copy,"approved"),"campaign policy invalidates approval after authorized edit");denied(api,owner,CHARACTER_EDIT,args("character",copyId,"revision",approvedRevision,"runtimeRevision",copy.get("runtimeRevision"),"section","identity","data",details));
        check(DashboardModel.editable(copy,false,owner.id().toString(),false),"owner may edit unbound campaign copy subject to server policy");var nonManagerView=copy.deepCopy();nonManagerView.addProperty("manager",false);check(!DashboardModel.editable(nonManagerView,false,outsider.id().toString(),false),"non-owner controller view cannot gain owner editing");check(!DashboardModel.editable(copy,false,owner.id().toString(),true),"active encounter presentation is read-only");denied(api,outsider,CHARACTER_GET,args("character",copyId));
        copy=ok(api,owner,CHARACTER_APPROVE,args("character",copyId,"revision",revision(copy)));UUID entity=UUID.randomUUID();repo.bind(owner,UUID.fromString(copyId),revision(copy),entity,owner.id());copy=ok(api,owner,CHARACTER_GET,args("character",copyId));check(!DashboardModel.editable(copy,false,owner.id().toString(),false)&&DashboardModel.restriction(copy,false,owner.id().toString(),false).contains("Bound"),"bound dashboard is explicitly read-only");denied(api,owner,MANUAL_UPDATE,args("scope","CAMPAIGN","character",copyId,"revision",revision(copy),"runtimeRevision",copy.get("runtimeRevision"),"change",SheetSections.JSON.toJsonTree(new RpgRecords.Change(RpgRecords.Action.INSPIRATION,"trackers","",0,0))));
        check(SheetSections.read(copy.getAsJsonObject("sheet"),"inventory").getAsJsonArray("items").size()==1,"campaign dashboard sees independent structured inventory");check(SheetSections.read(copy.getAsJsonObject("sheet"),"spellbook").getAsJsonArray("selections").size()==1,"campaign dashboard sees custom spellbook");check(SheetSections.read(copy.getAsJsonObject("sheet"),"features").getAsJsonArray("entries").get(0).getAsJsonObject().get("kind").getAsString().equals("CONDITION"),"structured condition visible without enforcement claim");check(RpgRecords.catalog("",0).get("total").getAsInt()==0,"standard spell catalog remains explicitly empty");
        for(int[] size:new int[][]{{320,180},{427,240},{854,480}}){var frame=UiLayout.frame(size[0],size[1],720);var list=DashboardModel.listArea(frame);check(list.fits(size[0],size[1])&&list.y()+list.height()<=frame.y()+frame.height()-30,"dashboard list clears footer "+Arrays.toString(size));}
        System.out.println("Dashboard UI checks passed: "+count);
    }
}
